/*
 Problem: 3518. Smallest Palindromic Rearrangement II
 Language: cpp
 Runtime: 7 ms (97.11%)
 Memory: 17.4 MB (24.54%)
 Tags: Hash Table, Math, String, Combinatorics, Counting
*/
class Solution {
    static const int LIM = 1'000'001;
    static const int MAX = 24;

    int C[MAX][MAX]{};

    void buildPascal() {
        C[0][0] = 1;

        for (int i = 1; i < MAX; ++i) {
            C[i][0] = C[i][i] = 1;

            for (int j = 1; j <= i / 2; ++j) {
                C[i][j] = C[i][i - j] = C[i - 1][j - 1] + C[i - 1][j];
            }
        }
    }

    int choose(int n, int k) {
        if (n < MAX) {
            return C[n][k];
        }

        k = min(k, n - k);

        long long res = 1;

        for (int i = 1; i <= k; ++i) {
            res = res * (n - i + 1) / i;

            if (res >= LIM) {
                return LIM;
            }
        }

        return res;
    }

    int countPermutations(const array<int, 26>& freq, int remain) {
        long long ways = 1;

        for (const auto& cnt : freq) {
            if (!cnt) {
                continue;
            }

            ways *= choose(remain, cnt);

            if (ways >= LIM) {
                return LIM;
            }

            remain -= cnt;
        }

        return ways;
    }

public:
    string smallestPalindrome(string s, int k) {
        buildPascal();

        const int n = s.size();
        const int half = n / 2;

        array<int, 26> freq{};

        for (int i = 0; i < half; ++i) {
            ++freq[s[i] - 'a'];
        }

        if (countPermutations(freq, half) < k) {
            return "";
        }

        string left;
        left.reserve(half);

        int remain = half;

        for (int i = 0; i < half; ++i) {
            for (int c = 0; c < 26; ++c) {
                if (!freq[c]) {
                    continue;
                }

                --freq[c];
                --remain;

                const int ways = countPermutations(freq, remain);

                if (ways >= k) {
                    left.push_back('a' + c);
                    break;
                }

                k -= ways;
                ++freq[c];
                ++remain;
            }
        }

        string right = left;
        reverse(right.begin(), right.end());

        if (n & 1) {
            left.push_back(s[half]);
        }

        left += right;
        return left;
    }
};
